/** Supplements the observed owner-facing first reds with the exact provider's bounded population proof. */
class LmdbExactPopulationQualificationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI TYPE = VF.createIRI("urn:population-owner:Patient");
	private static final IRI A = VF.createIRI("urn:population-owner:a");
	private static final IRI B = VF.createIRI("urn:population-owner:b");
	private static final IRI C = VF.createIRI("urn:population-owner:c");
	private static final IRI G = VF.createIRI("urn:population-owner:g");
	private static final IRI MISSING = VF.createIRI("urn:exact-provider:never-written");
	private static final IRI SELF = VF.createIRI("urn:exact-provider:self");

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void rawPositiveRequiresActualBothAnyPopulation(boolean nativeEvaluation, @TempDir Path root) throws Exception {
		try (Fixture fixture = new Fixture(root, nativeEvaluation, FrontierEstimatorMode.OFF)) {
			SimpleDataset implicit = new SimpleDataset();
			SimpleDataset physicalDefault = selectedDefault(null);
			SimpleDataset selectedGraph = selectedDefault(G);
			SimpleDataset namedOnly = new SimpleDataset();
			namedOnly.setExplicitReadDataset(true);
			namedOnly.addNamedGraph(G);
			for (Dataset selected : Arrays.asList(null, implicit, physicalDefault, selectedGraph, namedOnly)) {
				for (int plane : new int[] { FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.INFERRED,
						FrontierLeafProbe.BOTH_PLANES }) {
					try (Read read = fixture.read(plane, null, selected)) {
						read.entry(selected, (prepared, ignored) -> {
							StatementPattern pattern = firstPattern(prepared);
							EstimateContext context = actualContext(read, pattern);
							var source = source(read);
							assertEquals(3.0d, source.estimateExact(pattern), "unchanged raw physical BOTH/ANY API");
							boolean represented = plane == FrontierLeafProbe.BOTH_PLANES
									&& context.readPopulation() == LmdbFrontierReadPopulation.STORE_DEFAULTS;
							assertEquals(represented ? 3.0d : -1.0d, source.estimateExactForQuery(pattern, context));
							assertEquals(-1.0d, source.estimateExactForQuery(pattern,
									context.withGraphDomain(PlanningGraphDomain.unknown())),
									"unknown graph is not ANY proof");
							for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
								StatementPattern aliased = pattern.clone();
								setVariable(aliased, 3, Var.of("g", alias));
								assertEquals(-1.0d, source.estimateExactForQuery(aliased, context),
										"default-context aliases cannot inherit raw missing-graph zeros");
							}
							return null;
						});
					}
				}
			}
		}
	}

	@Test
	void typeAndSameSnapshotMissingTermProofsSurviveSelectedSinglePlaneReads(@TempDir Path root) throws Exception {
		SimpleDataset selected = selectedDefault(null);
		try (Fixture fixture = new Fixture(root, false, FrontierEstimatorMode.OFF);
				Read read = fixture.read(FrontierLeafProbe.EXPLICIT, null, selected)) {
			read.entry(selected, (prepared, ignored) -> {
				StatementPattern pattern = firstPattern(prepared);
				EstimateContext context = actualContext(read, pattern);
				var source = source(read);
				assertEquals(-1.0d, source.estimateExactForQuery(pattern, context));
				for (int position = 0; position < 3; position++) {
					StatementPattern absent = pattern.clone();
					setVariable(absent, position, Var.of("absent", MISSING));
					assertEquals(0L, genericRows(read, selected, absent));
					assertEquals(0.0d, source.estimateExactForQuery(absent, context),
							"same-store missing S/P/O IRI is independent of mapped graph support");
					assertEquals(-1.0d, source.estimateExactForQuery(absent,
							context.withReadPopulation(LmdbFrontierReadPopulation.UNSUPPORTED, 0, -1L)),
							"an enclosing pair alone cannot prove an opaque source uses this dictionary");
				}
				for (int position : new int[] { 0, 1, 3 }) {
					StatementPattern impossible = pattern.clone();
					Value invalid = position == 1 ? VF.createBNode("not-an-iri") : VF.createLiteral("not-a-resource");
					setVariable(impossible, position, Var.of("invalid", invalid));
					assertEquals(0L, genericRows(read, selected, impossible));
					assertEquals(0.0d, source.estimateExactForQuery(impossible, context),
							"RDF field type impossibility");
				}
				assertEquals(-1.0d, source.estimateExactForQuery(null, context));
				assertEquals(-1.0d, source.estimateExactForQuery(pattern, null));
				StatementPattern unnamed = pattern.clone();
				setVariable(unnamed, 0, Var.of((String) null));
				assertEquals(-1.0d, source.estimateExactForQuery(unnamed, context));
				return null;
			});
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void rawNameEqualitiesMustAgreeWithCompleteVarOccurrences(boolean nativeEvaluation, @TempDir Path root)
			throws Exception {
		try (Fixture fixture = new Fixture(root, nativeEvaluation, FrontierEstimatorMode.OFF)) {
			for (SailRepository target : new SailRepository[] { fixture.repository, fixture.oracle }) {
				try (var writer = target.getConnection()) {
					writer.begin();
					writer.add(A, SELF, A);
					writer.add(B, SELF, B, G);
					writer.add(A, SELF, B, G);
					((InferencerConnection) writer.getSailConnection()).addInferredStatement(C, SELF, C, G);
					writer.commit();
				}
			}
			try (Read read = fixture.read(FrontierLeafProbe.BOTH_PLANES, null, null)) {
				EstimateContext[] retainedContext = new EstimateContext[1];
				StatementPattern[] retainedPattern = new StatementPattern[1];
				read.entry(null, (prepared, ignored) -> {
					StatementPattern pattern = firstPattern(prepared);
					EstimateContext context = actualContext(read, pattern);
					var source = source(read);
					StatementPattern mixed = pattern.clone();
					setVariable(mixed, 2, Var.of(mixed.getSubjectVar().getName(), TYPE));
					assertEquals(3L, genericRows(read, null, mixed),
							"valued and unvalued Vars are distinct occurrences");
					assertEquals(0.0d, source.estimateExact(mixed), "raw name mask requires subject = object");
					assertEquals(-1.0d, source.estimateExactForQuery(mixed, context));
					StatementPattern repeated = pattern.clone();
					setVariable(repeated, 1, Var.of("predicate", SELF));
					setVariable(repeated, 2, repeated.getSubjectVar().clone());
					assertEquals(3L, genericRows(read, null, repeated));
					assertEquals(3.0d, source.estimateExactForQuery(repeated, context),
							"pure repeated variables retain exactness");
					StatementPattern anonymous = repeated.clone();
					setVariable(anonymous, 2, Var.of(anonymous.getSubjectVar().getName(), true));
					assertEquals(4L, genericRows(read, null, anonymous));
					assertEquals(-1.0d, source.estimateExactForQuery(anonymous, context));
					StatementPattern nested = repeated.clone();
					nested.getObjectVar().setGraphContextDepth(nested.getSubjectVar().getGraphContextDepth() + 1);
					assertEquals(4L, genericRows(read, null, nested));
					assertEquals(-1.0d, source.estimateExactForQuery(nested, context));
					StatementPattern constants = repeated.clone();
					setVariable(constants, 0, Var.of("fixed", A));
					setVariable(constants, 2, Var.of("fixed", B));
					assertEquals(1L, genericRows(read, null, constants));
					assertEquals(-1.0d, source.estimateExactForQuery(constants, context));
					setVariable(constants, 2, Var.of("fixed", A));
					assertEquals(1L, genericRows(read, null, constants));
					assertEquals(-1.0d, source.estimateExactForQuery(constants, context),
							"equal fixed RDF values alone do not prove equal physical IDs");
					retainedContext[0] = context;
					retainedPattern[0] = pattern.clone();
					return null;
				});
				assertEquals(-1.0d, source(read).estimateExactForQuery(retainedPattern[0], retainedContext[0]),
						"a retained epoch and Dataset enum cannot reopen the expired paired scope");
				assertEquals(3.0d, source(read).estimateExact(retainedPattern[0]),
						"direct physical API remains available");
			}
		}
	}

	private static EstimateContext actualContext(Read read, StatementPattern pattern) {
		assertTrue(read.runtime.hasPairedPlanningAuthority());
		long revision = read.runtime.physicalTripleStore().planningDataRevision();
		return EstimateContext.root(pattern, new QuadSnapshotIdentity(0L, 0L, revision), revision)
				.withReadPopulation(read.runtime.frontierReadPopulation(), read.runtime.frontierReadPlaneMask(),
						read.runtime.frontierReadSnapshotEpoch());
	}

	private static LmdbStatementPatternCardinalitySource source(Read read) {
		return new LmdbStatementPatternCardinalitySource(read.runtime.valueStore(), read.runtime.physicalTripleStore());
	}

	private static SimpleDataset selectedDefault(Resource graph) {
		SimpleDataset dataset = new SimpleDataset();
		dataset.setExplicitReadDataset(true);
		dataset.addDefaultGraph(graph);
		return dataset;
	}

	private static long genericRows(Read read, Dataset dataset, StatementPattern pattern) {
		long count = 0L;
		var generic = new DefaultEvaluationStrategy(read.source, dataset, null);
		try (var rows = generic.precompile(new QueryRoot(pattern.clone())).evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				rows.next();
				count++;
			}
		}
		return count;
	}

	private static StatementPattern firstPattern(TupleExpr expression) {
		StatementPattern[] result = new StatementPattern[1];
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (result[0] == null) {
					result[0] = pattern;
				}
			}
		});
		assertNotNull(result[0]);
		return result[0];
	}

	private static void setVariable(StatementPattern pattern, int position, Var variable) {
		switch (position) {
		case 0 -> pattern.replaceChildNode(pattern.getSubjectVar(), variable);
		case 1 -> pattern.replaceChildNode(pattern.getPredicateVar(), variable);
		case 2 -> pattern.replaceChildNode(pattern.getObjectVar(), variable);
		case 3 -> pattern.replaceChildNode(pattern.getContextVar(), variable);
		default -> throw new IllegalArgumentException("Unknown statement position " + position);
		}
	}
}
